  static String? resolve(String source, String localeTag) {
    final normalized = localeTag.replaceAll('_', '-');
    final exact = values[source]?[normalized];
    if (exact != null) return exact;
    final language = normalized.split('-').first.toLowerCase();
    for (final entry
        in values[source]?.entries ?? const <MapEntry<String, String>>[]) {
      if (entry.key.split('-').first.toLowerCase() == language) {
        return entry.value;
      }
    }
    return null;
  }
